#!/usr/bin/env node
// scripts/content-status.ts — `npm run content:status -- --dir <dir>` rebuilds
// `<dir>/ledger.generated.md` (default the repo root) from every module.yaml's own `status` field
// ("planned -> drafted -> gated -> reviewed -> accepted"). Read-only
// over content/; the ledger is the one file this script, and only this
// script, ever writes — never hand-edit it (see AGENTS.md: generated files are never hand-edited).

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { parse } from "yaml";
import { courseSchema, moduleFileSchema } from "@/lib/content/schemas";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const APP_ROOT = path.resolve(HERE, "..");
const REAL_ROOT = path.join(APP_ROOT, "content");
const dirIndex = process.argv.indexOf("--dir");
const LEDGER_DIR = dirIndex !== -1 ? process.argv[dirIndex + 1] : undefined;
const LEDGER = path.join(APP_ROOT, LEDGER_DIR ?? ".", "ledger.generated.md");

interface Row {
  stageId: string;
  stageTitle: string;
  moduleId: string;
  courseTitle: string;
  status: string;
  authored: boolean;
}

function readCourse(root: string) {
  const file = path.join(root, "course.yaml");
  if (!fs.existsSync(file)) return [];
  return courseSchema.parse(parse(fs.readFileSync(file, "utf8"))).stages;
}

function findModuleYaml(root: string, stageId: string, moduleId: string): string | null {
  const stagesDir = path.join(root, "stages");
  if (!fs.existsSync(stagesDir)) return null;
  for (const stageDir of fs.readdirSync(stagesDir, { withFileTypes: true })) {
    if (!stageDir.isDirectory() || !stageDir.name.startsWith(`${stageId}-`)) continue;
    const stagePath = path.join(stagesDir, stageDir.name);
    for (const moduleDir of fs.readdirSync(stagePath, { withFileTypes: true })) {
      if (!moduleDir.isDirectory() || !moduleDir.name.startsWith(`${moduleId}-`)) continue;
      const file = path.join(stagePath, moduleDir.name, "module.yaml");
      if (fs.existsSync(file)) return file;
    }
  }
  return null;
}

function buildRows(root: string): Row[] {
  const rows: Row[] = [];
  for (const stage of readCourse(root)) {
    for (const m of stage.modules) {
      const moduleYamlFile = findModuleYaml(root, stage.id, m.id);
      let status = m.status;
      let authored = false;
      if (moduleYamlFile) {
        const data = moduleFileSchema.parse(parse(fs.readFileSync(moduleYamlFile, "utf8")));
        status = data.status;
        authored = true;
      }
      rows.push({
        stageId: stage.id,
        stageTitle: stage.title,
        moduleId: m.id,
        courseTitle: m.title,
        status,
        authored,
      });
    }
  }
  return rows;
}

function main() {
  const rows = buildRows(REAL_ROOT);

  const counts = new Map<string, number>();
  for (const r of rows) counts.set(r.status, (counts.get(r.status) ?? 0) + 1);

  const lines: string[] = [
    "<!-- AUTO-GENERATED by `npm run content:status` (scripts/content-status.ts). Never hand-edit. -->",
    "# Content ledger",
    "",
    `Generated: ${new Date().toISOString()}`,
    "",
    "## Summary",
    "",
    "| status | count |",
    "|---|---|",
    ...["planned", "drafted", "gated", "reviewed", "accepted"].map(
      (s) => `| ${s} | ${counts.get(s) ?? 0} |`,
    ),
    `| **total** | **${rows.length}** |`,
    "",
    "## By stage",
    "",
  ];

  let currentStage: string | null = null;
  for (const r of rows) {
    if (r.stageId !== currentStage) {
      currentStage = r.stageId;
      lines.push(
        `### ${r.stageId} — ${r.stageTitle}`,
        "",
        "| module | title | status | authored |",
        "|---|---|---|---|",
      );
    }
    lines.push(`| ${r.moduleId} | ${r.courseTitle} | ${r.status} | ${r.authored ? "yes" : "no"} |`);
  }
  lines.push("");

  fs.mkdirSync(path.dirname(LEDGER), { recursive: true });
  fs.writeFileSync(LEDGER, `${lines.join("\n")}\n`, "utf8");
  console.log(`Wrote ${path.relative(APP_ROOT, LEDGER)} (${rows.length} modules).`);
}

main();
